TLM.f("Sancti/05-13",{"officium":"S. Roberti Bellarmino Episcopi Confessoris et Ecclesiæ Doctoris","rule":["Gloria","CredoDA"],"ruleInherited":["Gloria"],"fallback":"Commune/C4a","from":{"Introitus":"Commune/C4a","Evangelium":"Commune/C4a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui ad errórum insídias repelléndas et apostólicæ Sedis jura propugnánda, beátum Robértum Pontíficem tuum atque Doctórem mira eruditióne et virtúte decorásti: ejus méritis et intercessióne concéde; ut nos in veritátis amóre crescámus et errántium corda ad Ecclésiæ tuæ rédeant unitátem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 7:7-14"},{"k":"text","la":"Optávi, et datus est mihi sensus: et invocávi, et venit in me spíritus sapiéntiæ: et præpósui illam regnis et sédibus, et divítias nihil esse duxi in comparatióne illíus: nec comparávi illi lápidem pretiósum: quóniam omne aurum in comparatióne illíus arena est exígua, et tamquam lutum æstimábitur argéntum in conspéctu illíus. Super salútem et spéciem diléxi illam, et propósui pro luce habére illam: quóniam inexstinguíbile est lumen illíus. Venérunt autem mihi ómnia bona páriter cum illa, et innumerábilis honéstas per manus illíus, et lætátus sum in ómnibus: quóniam antecedébat me ista sapiéntia, et ignorábam, quóniam horum ómnium mater est. Quam sine fictióne dídici et sine invídia commúnico, et honestátem illíus non abscóndo. Infinítus enim thesáurus est homínibus: quo qui usi sunt, partícipes facti sunt amicítiæ Dei, propter disciplínæ dona commendáti."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja."},{"k":"text","la":"Qui ad justítiam erúdiunt multos quasi stellæ in perpétuas æternitátes. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Qui docti fúerint fulgébunt quasi splendor firmaménti. Allelúja.","mark":"V"},{"k":"text","la":"Qui ad justítiam erúdiunt multos quasi stellæ in perpétuas æternitátes. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 91:2; 91:3; 91:5"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"text","la":"Ad annuntiándum mane misericórdiam tuam, et veritátem tuam per noctem.","mark":"V"},{"k":"text","la":"Quia delectásti me, Dómine, in factúra tua, et in opéribus mánuum tuárum exsultábo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Ps 72:28"},{"k":"text","la":"Mihi autem adhærére Deo bonum est, pónere in Dómino Deo spem meam: ut annúntiem omnes prædicatiónes tuas in portis fíliæ Sion, allelúja."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, in odórem suavitátis offérimus: et præsta; ut, beáti Robérti mónitis et exémplis edócti, per sémitam mandatórum tuórum dilatáto corde currámus."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 5:14; 5:16"},{"k":"text","la":"Vos estis lux mundi: sic lúceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum qui in cœlis est, allelúja."}],"Postcommunio":[{"k":"text","la":"Sacraménta, quæ súmpsimus, Dómine Deus noster, in nobis fóveant caritátis ardórem: quo beátus Robértus veheménter accénsus, pro Ecclésia tua se júgiter impendébat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"38e223c3aa36ec5f":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženoga Roberta biskupa svoga i naučitelja ukrasio divnom učenošću i krepošću da suzbija zasjede zabluda i brani prava Apostolske Stolice, daj da po njegovim zaslugama i zagovoru rastemo u ljubavi prema istini a srcu zalutalih da se vrate k jedinstvu tvoje Crkve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"29cea5b0013ee55c":{"t":"Prikazujemo ti, Gospodine, darove na ugodan miris, a ti nam daj da poučeni opomenama i primjerima blaženog Roberta veselo hitimo po stazi tvojih zapovijedi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"664f0621f03bb9cd":{"t":"<i>Pomolimo se</i>.\nOtajstva koja smo primili, Gospodine Bože naš, neka u nama podržavaju žar ljubavi kao što se, njime snažno raspaljen, blaženi Robert neprestano žrtvovao za tvoju Crkvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"c970c462bacf8f65":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. <i>Aleluja</i>, <i>aleluja</i>."},"4234f6d249240914":{"t":"Mudr 7, 7-14\nČitanje knjige Mudrosti. Zaželio sam i dano mi je shvaćanje, molio sam i došao je u mene duh mudrosti koja mi je draža nego kraljevstva i prijestolja, a bogatstvo prema njoj nije ništa. Ne uspoređujem s njom dragi kamen, jer sve zlato prema njoj je kao sitan pijesak, a srebro je pored nje kao blato. Volim je više nego li zdravlje i ljepotu. Uzeo sam je kao svoje svjetlo što se ne može ugasiti. Zajedno s njom imam sva druga dobra, iz njezinih ruku. primam neizmjerno bogatstvo. Radujem se tome svemu, jer ova mudrost je moj vođa, a nisam znao, da je ona izvor sviju dobara. Naučio sam je bez himbe, i predajem je bez zavisti i ne sakrivam njezina blaga. Ona je neiscrpivo blago za sve ljude. Oni koji se njome služe postaju Božji prijatelji, preporučeni darovima nauke."},"086b04193b0b847d":{"t":"Dn 12, 3\n<i>Aleluja</i>, <i>aleluja</i>.\nUčeni ljudi će blistati kao sjaj nebeskog svoda. <i>Aleluja</i>.\nA oni koji mnoge poučavaju u pravednosti kao zvijezde kroz svu vječnost. <i>Aleluja</i>."},"a220bcd1476c8c48":{"t":"Mt 5, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Vi ste sol zemlje. Ako sol izvjetri, čim će se soliti? Za ništa više ne vrijedi, nego da se izbaci i da je ljudi pogaze. Vi ste svjetlo svijeta. Ne može se sakriti grad sazidan na gori. Niti se upaljuje svijeća i postavlja pod varićak, nego na svijećnjak da svijetli svima koji su u kući. Tako neka svijetli vaše svjetlo pred ljudima da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti da sam došao ukinuti zakon ili proroke! Nisam došao ukinuti nego dopuniti. Zaista vam kažem, dok stoji nebo i zemlja, neće od zakona nestati ni jednog slova, niti jednog znaka, dok se sve ne ispuni. Tko, dakle, dokine jednu od ovih najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom. A tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom."},"552bd02e49c6f458":{"t":"Ps 72, 28\nDobro mi je da sam uz Boga, da postavim u Gospodina Boga nađu svoju. Tako ću naviještati tvoja divna djela na vratima kćeri sionske. <i>Aleluja</i>."},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"},"fba8dc4360675934":{"t":"Mt 5, 14 i 16\nVi ste svjetlo svijeta. Neka tako svijetli vaše svjetlo pred ljudima da vide vaša dobra tijela i slave vašega nebeskog Oca. <i>Aleluja</i>."},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. Allelúja, allelúja."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. Allelúja, allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus qui in domo sunt. Sic lúceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}]}}});
